289	    /**
290	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
291	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
292	     * key component (normalized telephone, email and household identifier) is a duplicate.
293	     */
294	    private void rejectIdentityCollision(Owner owner) {
295	        String identityKey = OwnerIdentityKey.of(owner);
296	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
297	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
298	        if (collides) {
299	            throw new DuplicateOwnerException(identityKey);
300	        }
301	    }
