303	    /**
304	     * Assign the stable household identifier to the new owner and to every existing member of the
305	     * household, persisting the members whose identifier changes, and return the shared identifier.
306	     */
307	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
308	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
309	        for (Owner member : householdMembers) {
310	            if (!householdId.equals(member.getHouseholdId())) {
311	                member.setHouseholdId(householdId);
312	                ownerRepository.save(member);
313	            }
314	        }
315	        return householdId;
316	    }
317	
318	    @Override
319	    @Transactional
320	    public void saveOwner(Owner owner) throws DataAccessException {
321	        ownerRepository.save(owner);
322	    }
323	
324	    /**
325	     * Count the owners that already exist sharing this owner's first name and last name, compared
326	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
327	     */
328	    private int countNamesakes(Owner owner) {
329	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
330	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
331	            .count();
332	    }
333	
334	    /**
335	     * Find the existing owners that already share this owner's household, i.e. that have the same last name and
336	     * address compared case-insensitively and with runs of whitespace collapsed.
337	     */
338	    private List<Owner> findHouseholdMembers(Owner owner) {
339	        String address = TextNormalizer.normalize(owner.getAddress());
340	        if (address == null) {
341	            return List.of();
342	        }
343	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
344	            .filter(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())))
345	            .toList();
346	    }
347	
348	    @Override
349	    @Transactional(readOnly = true)
350	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
351	        return ownerRepository.findByLastName(lastName);
352	    }
353	
354	    @Override
355	    @Transactional(readOnly = true)
356	    public Collection<Visit> findVisitsByPetId(int petId) {
357	        return visitRepository.findByPetId(petId);
358	    }
359	
360	    @Override
361	    @Transactional(readOnly = true)
362	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
363	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
364	    }
365	
366	    private <T> T findEntityById(Supplier<T> supplier) {
367	        try {
368	            return supplier.get();
369	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
370	            // Just ignore not found exceptions for Jdbc/Jpa realization
371	            return null;
372	        }
373	    }
