40	     * @return the trimmed, whitespace-collapsed, lower-cased value, or {@code null} when
41	     * {@code value} is {@code null}
42	     */
43	    public static String normalize(String value) {
44	        if (value == null) {
45	            return null;
46	        }
47	        return WHITESPACE.matcher(value.strip()).replaceAll(" ").toLowerCase(Locale.ROOT);
48	    }
