18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.time.temporal.TemporalAdjusters;
22	
23	/**
24	 * Adjusts dates so that they fall on a business day (Monday to Friday).
25	 */
26	public final class BusinessDayAdjuster {
27	
28	    private BusinessDayAdjuster() {
29	    }
30	
31	    /**
32	     * Return the given date if it already falls on a business day, otherwise roll it forward to the
33	     * next Monday. A Saturday or Sunday is rolled forward; any weekday is returned unchanged.
34	     *
35	     * @param date the date to adjust
36	     * @return the date rolled forward to the next Monday when it lands on a weekend, or {@code null}
37	     *     if {@code date} is {@code null}
38	     */
39	    public static LocalDate toBusinessDay(LocalDate date) {
40	        if (date == null) {
41	            return null;
42	        }
43	        DayOfWeek dayOfWeek = date.getDayOfWeek();
44	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
45	            return date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
46	        }
47	        return date;
48	    }
49	}
