17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Optional;
20	
21	/**
22	 * The E.164 country calling codes this application recognises, each paired with the exact
23	 * number of national (subscriber) digits a valid number for that country carries.
24	 *
25	 * <p>Used to check a normalized number's national-number length against its country code.
26	 * A number whose calling code is not listed here has no per-country length rule.
27	 */
28	enum CountryCallingCode {
29	
30	    /** Australia: {@code '+61'} followed by 9 national digits. */
31	    AUSTRALIA("61", 9),
32	
33	    /** North American Numbering Plan: {@code '+1'} followed by 10 national digits. */
34	    NANP("1", 10);
35	
36	    private final String code;
37	    private final int nationalDigits;
38	
39	    CountryCallingCode(String code, int nationalDigits) {
40	        this.code = code;
41	        this.nationalDigits = nationalDigits;
42	    }
43	
44	    /**
45	     * The recognised calling code that prefixes the given digit string, if any. When more than
46	     * one would match, the longest (most specific) code wins.
47	     *
48	     * @param digits the digits of an E.164 number, without the leading {@code '+'}
49	     * @return the matching calling code, or {@link Optional#empty()} if none is recognised
50	     */
51	    static Optional<CountryCallingCode> forDigits(String digits) {
52	        CountryCallingCode match = null;
53	        for (CountryCallingCode candidate : values()) {
54	            if (digits.startsWith(candidate.code)
55	                    && (match == null || candidate.code.length() > match.code.length())) {
56	                match = candidate;
57	            }
58	        }
59	        return Optional.ofNullable(match);
60	    }
61	
62	    /**
63	     * Whether {@code digits} carries exactly the national-digit count this country requires.
64	     *
65	     * @param digits the digits of an E.164 number, without the leading {@code '+'}, that this
66	     * calling code prefixes
67	     */
68	    boolean hasValidNationalLength(String digits) {
69	        return digits.length() - code.length() == nationalDigits;
70	    }
71	}
